import sys
import xml.etree.ElementTree as ET
import json

def parse_xml_to_json(xml_path):
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
    except (ET.ParseError, IOError) as e:
        return None, f"error: {str(e)}"

    def parse_element(element):
        result = {}
        for child in element:
            if len(child) == 0:
                stripped_text = child.text.strip() if child.text else ""
                result[child.tag] = stripped_text
            else:
                nested = parse_element(child)
                result[child.tag] = nested
        return result

    config_children = {}
    for child in root:
        config_children[child.tag] = parse_element(child)

    return config_children

def main():
    if len(sys.argv) != 2:
        print("error: no XML file provided", file=sys.stderr)
        sys.exit(1)

    xml_path = sys.argv[1]
    data, error_msg = parse_xml_to_json(xml_path)

    if error_msg:
        print(error_msg, file=sys.stderr)
        sys.exit(1)

    print("read", xml_path, file=sys.stderr)
    json_output = json.dumps(data, indent=2, sort_keys=True)
    print(json_output)

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import json

def parse_xml_to_json(xml_element):
    result = {}
    for child in xml_element:
        if child.text and child.text.strip():
            result[child.tag] = child.text.strip()
        else:
            nested = parse_xml_to_json(child)
            if nested:  # Only add if there are nested elements
                result[child.tag] = nested
    return result

def main():
    if len(sys.argv) != 2:
        print("error: no XML file specified", file=sys.stderr)
        sys.exit(1)

    xml_path = sys.argv[1]
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
        if root.tag != 'config':
            print("error: root element is not <config>", file=sys.stderr)
            sys.exit(1)
    except ET.ParseError:
        print("error: invalid XML", file=sys.stderr)
        sys.exit(1)
    except IOError:
        print("error: cannot read file", file=sys.stderr)
        sys.exit(1)

    config_data = parse_xml_to_json(root)
    print(json.dumps(config_data, indent=2, sort_keys=True), end='')
    print(f"read {xml_path}", file=sys.stderr)

if __name__ == "__main__":
    main()
